export const byId=id=>catalog.find(x=>x.id===id);
export function select({query='',format='All',genre='All',mood='All',origin='All',savedOnly=false,saved=[]}={}){return catalog.filter(x=>(format==='All'||x.format===format)&&(!savedOnly||saved.includes(x.id))&&(genre==='All'||x.genre===genre)&&(mood==='All'||x.mood===mood)&&(origin==='All'||x.origin.startsWith(origin))&&[x.title,x.genre,x.description].join(' ').toLowerCase().includes(query.trim().toLowerCase()));}
export function restore(raw){const empty={saved:[],progress:{},spoilers:false,reduced:false};try{const x=JSON.parse(raw);const progress={};if(x?.progress&&typeof x.progress==='object')for(const [id,value]of Object.entries(x.progress)){const d=byId(id);if(d?.preview&&Number.isFinite(value))progress[id]=Math.max(0,Math.min(d.duration,value));}return {saved:[...new Set((Array.isArray(x?.saved)?x.saved:[]).filter(id=>byId(id)))],progress,spoilers:x?.spoilers===true,reduced:x?.reduced===true};}catch{return empty;}}
export function toggle(saved,id){return !byId(id)?saved:saved.includes(id)?saved.filter(x=>x!==id):[...saved,id];}
